/*
 * Kill switch for the legacy SvelteKit service worker.
 *
 * The SvelteKit app registered /service-worker.js. The React app uses the Workbox worker /sw.js
 * generated by vite-plugin-pwa (precache id `zellia-control`). A browser that still holds a
 * registration for /service-worker.js fetches this file on its next update check: it activates
 * immediately, deletes the caches the legacy worker created and unregisters itself. It has no
 * fetch handler, so it never serves anything.
 */

const LEGACY_RUNTIME_CACHES = ['images-cache', 'fonts-cache', 'api-cache'];
const LEGACY_PRECACHE_PREFIX = 'workbox-precache';

function isLegacyCache(name) {
  return LEGACY_RUNTIME_CACHES.includes(name) || name.startsWith(LEGACY_PRECACHE_PREFIX);
}

self.addEventListener('install', () => {
  void self.skipWaiting();
});

self.addEventListener('activate', event => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.allSettled(names.filter(isLegacyCache).map(name => caches.delete(name)));
      await self.registration.unregister();
    })()
  );
});
